<?php $hero=['title'=>'مسئله‌ات را بگو؛ از تجربه‌اش شروع کن.','text'=>'تجربه‌های واقعی را بخوان و مستقیم با کسی گفت‌وگو کن که این مسیر را رفته است.','eyebrow'=>'گفت‌وگو با کسی که این مسیر را رفته'];foreach($blocks as $b){if($b['type']==='hero'){$hero=$b;break;}} ?>
<section class="hero"><div><span class="eyebrow"><?= $this->icon('chat') ?><?= $this->copy($hero['eyebrow']??'') ?></span><h1><?= $this->copy($hero['title']) ?></h1><p><?= nl2br($this->copy($hero['text'])) ?></p>
<form class="home-search" method="get" action="<?= $this->h($this->url('/search')) ?>"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/search"><?php endif; ?><label class="sr-only" for="home-search">مسئله یا تجربه موردنظر</label><input id="home-search" name="q" maxlength="160" placeholder="دنبال چه تجربه‌ای هستی؟"><button class="primary">جست‌وجو</button></form></div><div class="hero-art"><span class="hero-orbit"></span><img class="hero-logo" src="/assets/morshed-logo.png" width="240" height="240" alt="مرشد؛ یک تجربه، یک مسیر تازه"><span class="hero-caption">تجربه، آغاز یک گفت‌وگو</span></div></section>
<div class="grid2 section"><a class="card service-card" href="<?= $this->h($this->url('/mentors')) ?>"><span class="service-icon"><?= $this->icon('users') ?></span><div><h2>گفت‌وگو با مرشد</h2><p class="muted small">یک هم‌صحبت باتجربه، کنار مسئلهٔ تو</p></div><?= $this->icon('arrow') ?></a><a class="card service-card" href="<?= $this->h($this->url('/experiences')) ?>"><span class="service-icon"><?= $this->icon('book') ?></span><div><h2>بانک تجربه‌ها</h2><p class="muted small">راه‌هایی که دیگران رفته‌اند</p></div><?= $this->icon('arrow') ?></a></div>
<?php foreach($blocks as $index=>$block): if($block['type']==='hero'){continue;}$kind=$block['type'];$all=match($kind){'mentors'=>'/mentors','experiences'=>'/experiences',default=>null}; ?>
