<?php if($block['text']): ?><p class="prose muted"><?= nl2br($this->copy($block['text'])) ?></p><?php endif; ?>
<?php if(in_array($kind,['mentors','experiences','topics'],true)): ?>
<?php if($block['items']): ?><div class="<?= $kind==='topics'?(($block['layout']??'rail')==='grid'?'topic-grid':'topic-rail'):(($block['layout']??'rail')==='grid'?'grid3':'card-rail') ?>" tabindex="0" role="region" aria-label="<?= $this->copy($block['title']) ?>؛ برای دیدن موارد بیشتر افقی پیمایش کنید">
<?php foreach($block['items'] as $item): if($kind==='topics'): ?><a class="topic-chip" href="<?= $this->h($this->url('/mentors?term='.$item['id'])) ?>"><?= $this->icon('topic') ?><?= $this->h($item['title']) ?></a>
<?php elseif($kind==='mentors'): ?><article class="card mentor-card"><div class="row"><?php if(!empty($item['avatar_asset_id'])): ?><img class="portrait" src="<?= $this->h($this->url('/content/asset?id='.$item['avatar_asset_id'])) ?>" width="60" height="60" loading="lazy" alt=""><?php else: ?><span class="avatar-symbol"><?= $this->icon('user') ?></span><?php endif; ?><div><h3><?= $this->h($item['display_name']) ?></h3><span class="tag">مرشد</span></div></div><p class="muted"><?= $this->h($item['headline']??'') ?></p><a class="card-action" href="<?= $this->h($this->url('/mentor/profile?id='.$item['user_id'])) ?>">شناخت مرشد و گفت‌وگو <?= $this->icon('chat') ?></a></article>
<?php else: ?><article class="card experience-card"><div class="experience-art" aria-hidden="true"><?= $this->icon('book') ?></div><h3><?= $this->h($item['title']) ?></h3><p class="muted small"><?= $this->h(!empty($item['summary'])?$item['summary']:(function_exists('mb_substr')?mb_substr($item['body']??'',0,120):'')) ?></p><p class="small">مرشد: <?= $this->h($item['display_name']??'') ?></p><a class="card-action" href="<?= $this->h($this->url('/experience?id='.$item['id'])) ?>">مطالعه و گفت‌وگو با مرشد <?= $this->icon('arrow') ?></a></article><?php endif; endforeach; ?></div>
<?php else: ?><p class="empty card muted">هنوز <?= $kind==='mentors'?'مرشد‌ای':($kind==='experiences'?'تجربه‌ای':'موضوعی') ?> برای این بخش منتشر نشده است.</p><?php endif; endif; ?></section><?php endforeach; ?>
